// Indice por texto (antes, ~800 strcmp por llamada: ~1 ms por frame en italiano/aleman/frances).
const Entry* FindEntry(const char* es) {
  static const std::unordered_map<std::string_view, const Entry*> index = [] {
    std::unordered_map<std::string_view, const Entry*> m;
    for (const Entry& e : kTable) m.emplace(e.es, &e);   // el primero gana, como la busqueda lineal
    return m;
  }();
  const auto it = index.find(es);
  return it == index.end() ? nullptr : it->second;
}

